const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const peoriaPoint = ee.Geometry.Point([-89.5889, 40.6936]);
  // Create a buffer around Peoria to represent agricultural land
  const aoi = peoriaPoint.buffer(30000); // 30 km buffer

  const sepStart = '2022-09-01';
  const sepEnd = '2022-09-30';
  const octStart = '2022-10-01';
  const octEnd = '2022-10-31';

  // Function to mask clouds and shadows from Sentinel-2 L2A data.
  function maskS2clouds(image) {
    const qa = image.select('SCL');
    // We want to keep:
    // 4: Vegetation
    // 5: Not vegetated
    // 7: Unclassified (often includes bare soil)
    // Mask out:
    // 0: NO_DATA
    // 1: SATURATED_OR_DEFECTIVE
    // 2: DARK_FEATURES (water, cloud shadows)
    // 3: CLOUD_SHADOWS
    // 6: WATER
    // 8: MEDIUM_PROBABILITY_CLOUD
    // 9: HIGH_PROBABILITY_CLOUD
    // 10: THIN_CIRRUS
    // 11: SNOW_ICE
    const goodQuality = qa.eq(4).or(qa.eq(5)).or(qa.eq(7));
    return image.updateMask(goodQuality);
  }

  // Function to calculate NDVI
  function addNDVI(image) {
    return image.addBands(image.normalizedDifference(['B8', 'B4']).rename('NDVI'));
  }

  // 2. Data Acquisition & Check
  const s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filter(ee.Filter.bounds(aoi))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 60)) // Filter out very cloudy images
    .map(maskS2clouds)
    .map(addNDVI)
    .select('NDVI'); // Select only the NDVI band

  const sepCollection = s2.filterDate(sepStart, sepEnd);
  const octCollection = s2.filterDate(octStart, octEnd);

  const sepSize = await sepCollection.size().getInfo();
  const octSize = await octCollection.size().getInfo();

  if (sepSize === 0 || octSize === 0) {
    console.log(`September Images: ${sepSize}`);
    console.log(`October Images: ${octSize}`);
    console.log("C1: Empty Collection (No images found for one or both comparison points).");
    return;
  }
  console.log(`September Images: ${sepSize}`);
  console.log(`October Images: ${octSize}`);

  // Create median composites
  const sepComposite = sepCollection.median();
  const octComposite = octCollection.median();

  // 3. Processing (Calculate pixel count to detect C2)
  const scale = 1000; // Use a coarser scale for regional mean to avoid memory issues

  const sepPixels = await sepComposite.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9,
  }).get('NDVI').getInfo();

  const octPixels = await octComposite.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9,
  }).get('NDVI').getInfo();

  if (sepPixels === 0 || octPixels === 0) {
    console.log(`September Valid Pixels: ${sepPixels}`);
    console.log(`October Valid Pixels: ${octPixels}`);
    console.log("C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).");
    return;
  }
  console.log(`September Valid Pixels: ${sepPixels}`);
  console.log(`October Valid Pixels: ${octPixels}`);

  // 4. Calculation
  const sepNDVI = await sepComposite.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9,
  }).get('NDVI').getInfo();

  const octNDVI = await octComposite.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9,
  }).get('NDVI').getInfo();

  // 5. Validation & Final Answer
  if (sepNDVI === null || isNaN(sepNDVI) || octNDVI === null || isNaN(octNDVI)) {
    console.log(`September NDVI: ${sepNDVI}`);
    console.log(`October NDVI: ${octNDVI}`);
    console.log("C3: Calculation Failure (Result is None, NaN, or invalid).");
    return;
  }

  console.log(`September Mean NDVI: ${sepNDVI.toFixed(4)}`);
  console.log(`October Mean NDVI: ${octNDVI.toFixed(4)}`);

  // "More brown fields" implies lower NDVI
  if (octNDVI < sepNDVI) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
